import os

struct LaunchTimer {
    static let signposter = OSSignposter(subsystem: "com.app", category: "Launch")

    static func run(_ name: StaticString, work: () -> Int) -> Int {
        let id = signposter.makeSignpostID()
        let state = signposter.beginInterval(name, id: id)
        defer { signposter.endInterval(name, state) }
        return work()
    }
}

let items = LaunchTimer.run("LoadFeed") { 12 }
print("Items: \(items)")

final class LaunchQueue {
    private var deferred: [() -> Void] = []

    func scheduleAfterFirstFrame(_ task: @escaping () -> Void) {
        deferred.append(task)
    }

    func flush() {
        print("First frame drawn")
        for task in deferred { task() }
    }
}

let queue = LaunchQueue()
queue.scheduleAfterFirstFrame { print("Logs ready") }
print("Scene connected")
queue.flush()

