final class LaunchCoordinator {
    var deferredTasks: [() -> Void] = []

    func didFinishLaunching() {
        print("UI ready")
        deferredTasks.append { self.setupAnalytics() }
    }

    func firstFrameDidDraw() {
        for task in deferredTasks {
            task()
        }
        deferredTasks.removeAll()
    }

    func setupAnalytics() {
        print("Analytics ready")
    }
}

let app = LaunchCoordinator()
app.didFinishLaunching()
app.firstFrameDidDraw()

